import { useUIStore } from '@/store/useUIStore'
import { CANVAS_DEFAULTS } from '@/constants'

interface CanvasGridProps {
  zoom: number
  panX: number
  panY: number
}

export function CanvasGrid({ zoom, panX, panY }: CanvasGridProps) {
  const { gridVisible } = useUIStore()

  if (!gridVisible) return null

  const gridSize = CANVAS_DEFAULTS.GRID_SIZE * zoom
  const dotSize = CANVAS_DEFAULTS.GRID_DOT_SIZE * zoom

  // Generate grid pattern
  const patternId = 'dot-grid-pattern'

  return (
    <svg
      className="absolute inset-0 pointer-events-none"
      style={{
        transform: `translate(${panX}px, ${panY}px)`,
        transformOrigin: '0 0',
      }}
    >
      <defs>
        <pattern
          id={patternId}
          x="0"
          y="0"
          width={gridSize}
          height={gridSize}
          patternUnits="userSpaceOnUse"
        >
          <circle
            cx={gridSize / 2}
            cy={gridSize / 2}
            r={dotSize}
            fill="currentColor"
            className="text-gray-300 dark:text-gray-600"
          />
        </pattern>
      </defs>
      <rect
        x="0"
        y="0"
        width="100%"
        height="100%"
        fill={`url(#${patternId})`}
        className="text-gray-300 dark:text-gray-600"
      />
    </svg>
  )
}
