import { useEffect, useState, useRef } from 'react'
import { useParams } from 'react-router-dom'
import { useCanvasStore } from '@/store/useCanvasStore'
import { useProjectsStore } from '@/store/useProjectsStore'
import { useAuthStore } from '@/store/useAuthStore'
import { useUIStore } from '@/store/useUIStore'
import { CanvasToolbar } from '@/components/canvas/CanvasToolbar'
import { CanvasGrid } from '@/components/canvas/CanvasGrid'
import { ZoomControls } from '@/components/canvas/ZoomControls'
import { wsService } from '@/services/websocket'
import { generateId } from '@/utils/canvas'

export function CanvasPage() {
  const { canvasId } = useParams<{ canvasId: string }>()
  const containerRef = useRef<HTMLDivElement>(null)

  const { user } = useAuthStore()
  const {
    nodes,
    groups,
    domains,
    connections,
    zoom,
    panX,
    panY,
    selectedIds,
    setCanvasId,
    setZoom,
    setPan,
    setEditingId,
    clearCanvas,
  } = useCanvasStore()

  const {
    currentTool,
    dragMode,
    setCurrentTool,
    toggleGrid,
  } = useUIStore()

  // Initialize canvas
  useEffect(() => {
    if (!canvasId) return

    const id = parseInt(canvasId)
    setCanvasId(id)

    // Connect to WebSocket for collaboration
    if (user && canvasId) {
      wsService.connect({
        canvasId: id,
        token: (user as any).token || '',
        onUsersChange: (users) => {
          console.log('Users changed:', users)
        },
        onCursorsChange: (cursors) => {
          console.log('Cursors changed:', cursors)
        },
      })
    }

    return () => {
      wsService.disconnect()
      clearCanvas()
    }
  }, [canvasId, user])

  // Handle keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Don't handle shortcuts when typing in input fields
      if (
        e.target instanceof HTMLInputElement ||
        e.target instanceof HTMLTextAreaElement
      ) {
        return
      }

      // Tool shortcuts
      if (e.key === 'n' || e.key === 'N') {
        setCurrentTool('node')
      } else if (e.key === 'r' || e.key === 'R') {
        setCurrentTool('domain')
      } else if (e.key === 'l' || e.key === 'L') {
        setCurrentTool('connection')
      } else if (e.key === 'g' || e.key === 'G') {
        if (e.ctrlKey || e.metaKey) {
          // Ctrl+G: Create group
        } else {
          toggleGrid()
        }
      } else if (e.key === 'Escape') {
        setCurrentTool('select')
        setEditingId(null)
      }

      // Zoom shortcuts
      if ((e.ctrlKey || e.metaKey) && e.key === '0') {
        e.preventDefault()
        setZoom(1)
        setPan(0, 0)
      } else if ((e.ctrlKey || e.metaKey) && (e.key === '=' || e.key === '+')) {
        e.preventDefault()
        setZoom(Math.min(zoom + 0.1, 5))
      } else if ((e.ctrlKey || e.metaKey) && e.key === '-') {
        e.preventDefault()
        setZoom(Math.max(zoom - 0.1, 0.1))
      }
    }

    window.addEventListener('keydown', handleKeyDown)

    return () => {
      window.removeEventListener('keydown', handleKeyDown)
    }
  }, [zoom, setCurrentTool, setZoom, setPan, toggleGrid, setEditingId])

  // Handle mouse wheel for zooming and panning
  const handleWheel = (e: React.WheelEvent) => {
    if (e.ctrlKey || e.metaKey) {
      // Zoom
      e.preventDefault()
      const delta = e.deltaY * -0.001
      const newZoom = Math.min(Math.max(zoom + delta, 0.1), 5)
      setZoom(newZoom)
    } else if (e.shiftKey) {
      // Horizontal pan
      e.preventDefault()
      setPan(panX - e.deltaY, panY)
    } else {
      // Vertical pan
      e.preventDefault()
      setPan(panX, panY - e.deltaY)
    }
  }

  // Handle canvas click
  const handleCanvasClick = (e: React.MouseEvent) => {
    if (currentTool === 'node') {
      const rect = e.currentTarget.getBoundingClientRect()
      const x = (e.clientX - rect.left - panX) / zoom
      const y = (e.clientY - rect.top - panY) / zoom

      // Create new node
      const newNode = {
        id: generateId('node'),
        x: dragMode === 'grid' ? Math.round(x / 20) * 20 : x,
        y: dragMode === 'grid' ? Math.round(y / 20) * 20 : y,
        width: 200,
        height: 120,
        content: 'New Node',
        color: '#ffffff',
        borderColor: '#e5e7eb',
        borderWidth: 1,
        borderRadius: 8,
        fontSize: 14,
        textAlign: 'center' as const,
        collapsed: false,
        locked: false,
      }

      // Add node logic would go here
      setCurrentTool('select')
    }
  }

  return (
    <div className="h-full flex flex-col bg-gray-100 dark:bg-gray-900">
      {/* Canvas Toolbar */}
      <CanvasToolbar />

      {/* Canvas Container */}
      <div
        ref={containerRef}
        className="flex-1 relative overflow-hidden"
        onWheel={handleWheel}
        onClick={handleCanvasClick}
        style={{
          cursor: currentTool === 'node' ? 'crosshair' : currentTool === 'domain' ? 'cell' : 'default',
        }}
      >
        {/* Grid */}
        <CanvasGrid zoom={zoom} panX={panX} panY={panY} />

        {/* Canvas content */}
        <div
          className="absolute"
          style={{
            transform: `scale(${zoom}) translate(${panX / zoom}px, ${panY / zoom}px)`,
            transformOrigin: '0 0',
          }}
        >
          {/* Render domains */}
          {Array.from(domains.values()).map((domain) => (
            <div
              key={domain.id}
              className="absolute border"
              style={{
                left: domain.x,
                top: domain.y,
                width: domain.width,
                height: domain.height,
                backgroundColor: domain.backgroundColor,
                borderColor: domain.borderColor,
                borderWidth: domain.borderWidth,
              }}
            >
              {domain.titleVisible && domain.name && (
                <div className="absolute -top-6 left-0 px-2 py-1 bg-gray-200 dark:bg-gray-700 rounded text-xs font-medium">
                  {domain.name}
                </div>
              )}
            </div>
          ))}

          {/* Render connections */}
          <svg className="absolute inset-0 pointer-events-none" style={{ overflow: 'visible' }}>
            <defs>
              <marker
                id="arrowhead"
                markerWidth="10"
                markerHeight="7"
                refX="9"
                refY="3.5"
                orient="auto"
              >
                <polygon points="0 0, 10 3.5, 0 7" fill="#6b7280" />
              </marker>
            </defs>
            {Array.from(connections.values()).map((conn) => {
              const fromNode = nodes.get(conn.fromNodeId)
              const toNode = nodes.get(conn.toNodeId)
              if (!fromNode || !toNode) return null

              const fromX = fromNode.x + fromNode.width / 2
              const fromY = fromNode.y + fromNode.height / 2
              const toX = toNode.x + toNode.width / 2
              const toY = toNode.y + toNode.height / 2

              return (
                <line
                  key={conn.id}
                  x1={fromX}
                  y1={fromY}
                  x2={toX}
                  y2={toY}
                  stroke={conn.color}
                  strokeWidth={conn.width}
                  strokeDasharray={conn.style === 'dashed' ? '5,5' : conn.style === 'dotted' ? '2,2' : undefined}
                  markerEnd={conn.arrowType === 'end' || conn.arrowType === 'both' ? 'url(#arrowhead)' : undefined}
                />
              )
            })}
          </svg>

          {/* Render groups */}
          {Array.from(groups.values()).map((group) => (
            <div
              key={group.id}
              className="absolute border-2 rounded-lg"
              style={{
                left: group.x,
                top: group.y,
                width: group.width,
                height: group.height,
                borderColor: group.borderColor,
                backgroundColor: group.backgroundColor,
                borderRadius: group.borderRadius,
              }}
            >
              <div className="absolute -top-6 left-0 px-2 py-1 text-xs font-medium" style={{ color: group.borderColor }}>
                {group.name}
              </div>
            </div>
          ))}

          {/* Render nodes */}
          {Array.from(nodes.values()).map((node) => {
            const isSelected = selectedIds.includes(node.id)
            return (
              <div
                key={node.id}
                className="absolute border rounded-lg shadow-sm p-4 cursor-move hover:shadow-md transition-shadow"
                style={{
                  left: node.x,
                  top: node.y,
                  width: node.width,
                  height: node.height,
                  backgroundColor: node.color,
                  borderColor: isSelected ? '#3b82f6' : node.borderColor,
                  borderWidth: isSelected ? 2 : node.borderWidth,
                  borderRadius: node.borderRadius,
                }}
              >
                <div
                  className="w-full h-full flex items-center justify-center text-center"
                  style={{
                    fontSize: node.fontSize,
                    textAlign: node.textAlign,
                  }}
                >
                  {node.content || 'Empty node'}
                </div>
              </div>
            )
          })}
        </div>
      </div>

      {/* Zoom Controls */}
      <ZoomControls />
    </div>
  )
}
