import { useState } from 'react'
import { Plus, Folder, FolderOpen, FileText, Trash2, MoreVertical } from 'lucide-react'
import { useNavigate } from 'react-router-dom'
import { useProjectsStore } from '@/store/useProjectsStore'
import { useUIStore } from '@/store/useUIStore'
import clsx from 'clsx'

interface SidebarProps {
  open: boolean
}

export function Sidebar({ open }: SidebarProps) {
  const navigate = useNavigate()
  const { canvases, folders, currentProject, createCanvas, createFolder } = useProjectsStore()
  const { addToast } = useUIStore()
  const [expandedFolders, setExpandedFolders] = useState<Set<number>>(new Set())

  const handleCreateCanvas = async () => {
    if (!currentProject) {
      addToast({ type: 'warning', title: 'No project selected', message: 'Please select a project first' })
      return
    }

    try {
      await createCanvas(currentProject.id, {
        name: `Untitled Canvas ${canvases.length + 1}`,
        project_id: currentProject.id,
      })
    } catch (error) {
      addToast({ type: 'error', title: 'Failed to create canvas', message: error instanceof Error ? error.message : 'Unknown error' })
    }
  }

  const handleCreateFolder = async () => {
    if (!currentProject) {
      addToast({ type: 'warning', title: 'No project selected', message: 'Please select a project first' })
      return
    }

    try {
      await createFolder(currentProject.id, {
        name: 'New Folder',
        project_id: currentProject.id,
        parent_id: null,
        sort_order: 0,
      })
    } catch (error) {
      addToast({ type: 'error', title: 'Failed to create folder', message: error instanceof Error ? error.message : 'Unknown error' })
    }
  }

  const toggleFolder = (folderId: number) => {
    setExpandedFolders((prev) => {
      const next = new Set(prev)
      if (next.has(folderId)) {
        next.delete(folderId)
      } else {
        next.add(folderId)
      }
      return next
    })
  }

  const rootCanvases = canvases.filter((c) => !c.folder_id)

  return (
    <aside
      className={clsx(
        'bg-white dark:bg-gray-800 border-r border-gray-200 dark:border-gray-700 flex flex-col transition-all duration-200',
        open ? 'w-64' : 'w-0'
      )}
    >
      {/* Header */}
      <div className="h-12 border-b border-gray-200 dark:border-gray-700 flex items-center justify-between px-4">
        <h2 className="font-semibold text-gray-800 dark:text-white">Canvases</h2>
        <div className="flex items-center gap-1">
          <button
            onClick={handleCreateFolder}
            className="p-1 rounded hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400"
            title="New Folder"
          >
            <Folder className="w-4 h-4" />
          </button>
          <button
            onClick={handleCreateCanvas}
            className="p-1 rounded hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400"
            title="New Canvas (Ctrl+N)"
          >
            <Plus className="w-4 h-4" />
          </button>
        </div>
      </div>

      {/* Canvas List */}
      <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
        {/* Render folders */}
        {folders.map((folder) => (
          <div key={folder.id} className="mb-2">
            <button
              onClick={() => toggleFolder(folder.id)}
              className="w-full flex items-center gap-2 px-2 py-1 rounded hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-700 dark:text-gray-300"
            >
              {expandedFolders.has(folder.id) ? (
                <FolderOpen className="w-4 h-4" />
              ) : (
                <Folder className="w-4 h-4" />
              )}
              <span className="text-sm flex-1 text-left">{folder.name}</span>
            </button>

            {expandedFolders.has(folder.id) && (
              <div className="ml-4 mt-1">
                {canvases
                  .filter((c) => c.folder_id === folder.id)
                  .map((canvas) => (
                    <CanvasItem key={canvas.id} canvas={canvas} />
                  ))}
              </div>
            )}
          </div>
        ))}

        {/* Render root canvases */}
        {rootCanvases.map((canvas) => (
          <CanvasItem key={canvas.id} canvas={canvas} />
        ))}
      </div>
    </aside>
  )
}

function CanvasItem({ canvas }: { canvas: any }) {
  const navigate = useNavigate()

  return (
    <button
      onClick={() => navigate(`/canvas/${canvas.id}`)}
      className="w-full flex items-center gap-2 px-2 py-1.5 rounded hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-700 dark:text-gray-300 group"
    >
      <FileText className="w-4 h-4 text-gray-400" />
      <span className="text-sm flex-1 text-left truncate">{canvas.name}</span>
      <button
        className="opacity-0 group-hover:opacity-100 p-1 rounded hover:bg-gray-200 dark:hover:bg-gray-600"
        onClick={(e) => {
          e.stopPropagation()
          // Handle context menu
        }}
      >
        <MoreVertical className="w-3 h-3" />
      </button>
    </button>
  )
}
