import { create } from 'zustand'
import type { Node, NodeGroup, Domain, Connection } from '@/types'
import { NODE_DEFAULTS, CANVAS_DEFAULTS } from '@/constants'

interface CanvasState {
  // Canvas data
  nodes: Map<string, Node>
  groups: Map<string, NodeGroup>
  domains: Map<string, Domain>
  connections: Map<string, Connection>

  // View state
  zoom: number
  panX: number
  panY: number

  // Selection state
  selectedIds: string[]
  hoveredId: string | null

  // Editing state
  editingId: string | null

  // Canvas state
  canvasId: number | null
  canvasName: string | null
  isDirty: boolean
  isLoading: boolean

  // Actions
  setCanvasId: (id: number | null) => void
  setCanvasName: (name: string | null) => void

  // Node actions
  addNode: (node: Node) => void
  updateNode: (id: string, updates: Partial<Node>) => void
  removeNode: (id: string) => void
  duplicateNode: (id: string) => void

  // Group actions
  addGroup: (group: NodeGroup) => void
  updateGroup: (id: string, updates: Partial<NodeGroup>) => void
  removeGroup: (id: string) => void

  // Domain actions
  addDomain: (domain: Domain) => void
  updateDomain: (id: string, updates: Partial<Domain>) => void
  removeDomain: (id: string) => void

  // Connection actions
  addConnection: (connection: Connection) => void
  updateConnection: (id: string, updates: Partial<Connection>) => void
  removeConnection: (id: string) => void

  // Selection actions
  setSelectedIds: (ids: string[]) => void
  addToSelection: (id: string) => void
  removeFromSelection: (id: string) => void
  clearSelection: () => void

  // View actions
  setZoom: (zoom: number) => void
  setPan: (x: number, y: number) => void
  resetView: () => void

  // Edit state
  setEditingId: (id: string | null) => void
  setHoveredId: (id: string | null) => void

  // Dirty state
  setDirty: (dirty: boolean) => void

  // Bulk actions
  setCanvasData: (data: {
    nodes?: Node[]
    groups?: NodeGroup[]
    domains?: Domain[]
    connections?: Connection[]
  }) => void
  clearCanvas: () => void
}

export const useCanvasStore = create<CanvasState>((set, get) => ({
  // Initial state
  nodes: new Map(),
  groups: new Map(),
  domains: new Map(),
  connections: new Map(),

  zoom: CANVAS_DEFAULTS.DEFAULT_ZOOM,
  panX: 0,
  panY: 0,

  selectedIds: [],
  hoveredId: null,
  editingId: null,

  canvasId: null,
  canvasName: null,
  isDirty: false,
  isLoading: false,

  // Canvas ID
  setCanvasId: (id) => set({ canvasId: id }),
  setCanvasName: (name) => set({ canvasName: name }),

  // Node actions
  addNode: (node) =>
    set((state) => {
      const nodes = new Map(state.nodes)
      nodes.set(node.id, node)
      return { nodes, isDirty: true }
    }),

  updateNode: (id, updates) =>
    set((state) => {
      const nodes = new Map(state.nodes)
      const node = nodes.get(id)
      if (node) {
        nodes.set(id, { ...node, ...updates })
        return { nodes, isDirty: true }
      }
      return state
    }),

  removeNode: (id) =>
    set((state) => {
      const nodes = new Map(state.nodes)
      nodes.delete(id)
      // Also remove connections connected to this node
      const connections = new Map(state.connections)
      for (const [connId, conn] of connections) {
        if (conn.fromNodeId === id || conn.toNodeId === id) {
          connections.delete(connId)
        }
      }
      return { nodes, connections, isDirty: true }
    }),

  duplicateNode: (id) => {
    const state = get()
    const node = state.nodes.get(id)
    if (!node) return

    const newNode: Node = {
      ...node,
      id: `${node.id}-copy-${Date.now()}`,
      x: node.x + 20,
      y: node.y + 20,
    }
    get().addNode(newNode)
    get().setSelectedIds([newNode.id])
  },

  // Group actions
  addGroup: (group) =>
    set((state) => {
      const groups = new Map(state.groups)
      groups.set(group.id, group)
      return { groups, isDirty: true }
    }),

  updateGroup: (id, updates) =>
    set((state) => {
      const groups = new Map(state.groups)
      const group = groups.get(id)
      if (group) {
        groups.set(id, { ...group, ...updates })
        return { groups, isDirty: true }
      }
      return state
    }),

  removeGroup: (id) =>
    set((state) => {
      const groups = new Map(state.groups)
      groups.delete(id)
      return { groups, isDirty: true }
    }),

  // Domain actions
  addDomain: (domain) =>
    set((state) => {
      const domains = new Map(state.domains)
      domains.set(domain.id, domain)
      return { domains, isDirty: true }
    }),

  updateDomain: (id, updates) =>
    set((state) => {
      const domains = new Map(state.domains)
      const domain = domains.get(id)
      if (domain) {
        domains.set(id, { ...domain, ...updates })
        return { domains, isDirty: true }
      }
      return state
    }),

  removeDomain: (id) =>
    set((state) => {
      const domains = new Map(state.domains)
      domains.delete(id)
      return { domains, isDirty: true }
    }),

  // Connection actions
  addConnection: (connection) =>
    set((state) => {
      const connections = new Map(state.connections)
      connections.set(connection.id, connection)
      return { connections, isDirty: true }
    }),

  updateConnection: (id, updates) =>
    set((state) => {
      const connections = new Map(state.connections)
      const connection = connections.get(id)
      if (connection) {
        connections.set(id, { ...connection, ...updates })
        return { connections, isDirty: true }
      }
      return state
    }),

  removeConnection: (id) =>
    set((state) => {
      const connections = new Map(state.connections)
      connections.delete(id)
      return { connections, isDirty: true }
    }),

  // Selection actions
  setSelectedIds: (ids) => set({ selectedIds: ids }),
  addToSelection: (id) =>
    set((state) => ({
      selectedIds: state.selectedIds.includes(id)
        ? state.selectedIds
        : [...state.selectedIds, id],
    })),
  removeFromSelection: (id) =>
    set((state) => ({
      selectedIds: state.selectedIds.filter((sid) => sid !== id),
    })),
  clearSelection: () => set({ selectedIds: [] }),

  // View actions
  setZoom: (zoom) => set({ zoom }),
  setPan: (x, y) => set({ panX: x, panY: y }),
  resetView: () =>
    set({
      zoom: CANVAS_DEFAULTS.DEFAULT_ZOOM,
      panX: 0,
      panY: 0,
    }),

  // Edit state
  setEditingId: (id) => set({ editingId: id }),
  setHoveredId: (id) => set({ hoveredId: id }),

  // Dirty state
  setDirty: (dirty) => set({ isDirty: dirty }),

  // Bulk actions
  setCanvasData: (data) =>
    set((state) => ({
      nodes: data.nodes ? new Map(data.nodes.map((n) => [n.id, n])) : state.nodes,
      groups: data.groups ? new Map(data.groups.map((g) => [g.id, g])) : state.groups,
      domains: data.domains ? new Map(data.domains.map((d) => [d.id, d])) : state.domains,
      connections: data.connections
        ? new Map(data.connections.map((c) => [c.id, c]))
        : state.connections,
      isDirty: false,
    })),

  clearCanvas: () =>
    set({
      nodes: new Map(),
      groups: new Map(),
      domains: new Map(),
      connections: new Map(),
      zoom: CANVAS_DEFAULTS.DEFAULT_ZOOM,
      panX: 0,
      panY: 0,
      selectedIds: [],
      hoveredId: null,
      editingId: null,
      isDirty: false,
    }),
}))
