import { useState } from 'react'
import { Plus, Search, MoreVertical, Copy, Trash2 } from 'lucide-react'
import { useProjectsStore } from '@/store/useProjectsStore'
import { useUIStore } from '@/store/useUIStore'
import { useCanvasStore } from '@/store/useCanvasStore'
import clsx from 'clsx'

interface NodePoolPanelProps {
  open: boolean
}

export function NodePoolPanel({ open }: NodePoolPanelProps) {
  const { nodePool, addToNodePool, removeFromNodePool } = useProjectsStore()
  const { addToast } = useUIStore()
  const { nodes } = useCanvasStore()
  const [searchQuery, setSearchQuery] = useState('')

  const handleAddToPool = async () => {
    const selectedNode = Array.from(nodes.values())[0]
    if (!selectedNode) {
      addToast({ type: 'warning', title: 'No node selected', message: 'Please select a node to add to the pool' })
      return
    }

    try {
      await addToNodePool(
        1,
        { project_id: 1, name: selectedNode.content || 'Untitled', content: JSON.stringify(selectedNode), type: 'text', color: selectedNode.color, tags: null, image_url: null, created_by: 1 }
      )
      addToast({ type: 'success', title: 'Added to pool', message: 'Node has been added to the pool' })
    } catch (error) {
      addToast({ type: 'error', title: 'Failed to add', message: error instanceof Error ? error.message : 'Unknown error' })
    }
  }

  const handleRemoveFromPool = async (id: number) => {
    try {
      await removeFromNodePool(id)
      addToast({ type: 'success', title: 'Removed from pool', message: 'Node has been removed from the pool' })
    } catch (error) {
      addToast({ type: 'error', title: 'Failed to remove', message: error instanceof Error ? error.message : 'Unknown error' })
    }
  }

  const filteredPool = nodePool.filter((card) =>
    card.name.toLowerCase().includes(searchQuery.toLowerCase())
  )

  return (
    <aside
      className={clsx(
        'bg-white dark:bg-gray-800 border-l border-gray-200 dark:border-gray-700 flex flex-col transition-all duration-200',
        open ? 'w-64' : 'w-0'
      )}
    >
      {/* Header */}
      <div className="h-12 border-b border-gray-200 dark:border-gray-700 flex items-center justify-between px-4">
        <h2 className="font-semibold text-gray-800 dark:text-white">Node Pool</h2>
        <button
          onClick={handleAddToPool}
          className="p-1 rounded hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400"
          title="Add Selected to Pool (Ctrl+Shift+A)"
        >
          <Plus className="w-4 h-4" />
        </button>
      </div>

      {/* Search */}
      <div className="p-3 border-b border-gray-200 dark:border-gray-700">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <input
            type="text"
            placeholder="Search nodes..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-9 pr-3 py-2 text-sm bg-gray-100 dark:bg-gray-700 border-0 rounded-lg focus:ring-2 focus:ring-blue-500 text-gray-800 dark:text-white placeholder-gray-500"
          />
        </div>
      </div>

      {/* Node Cards */}
      <div className="flex-1 overflow-y-auto custom-scrollbar p-3 space-y-2">
        {filteredPool.map((card) => (
          <NodeCardItem
            key={card.id}
            card={card}
            onRemove={() => handleRemoveFromPool(card.id)}
          />
        ))}

        {filteredPool.length === 0 && (
          <div className="text-center py-8 text-gray-500 dark:text-gray-400">
            <p className="text-sm">No nodes in pool</p>
            <p className="text-xs mt-1">Select a node and click + to add</p>
          </div>
        )}
      </div>
    </aside>
  )
}

function NodeCardItem({ card, onRemove }: { card: any; onRemove: () => void }) {
  const { addNode } = useCanvasStore()

  const handleUseCard = () => {
    try {
      const nodeData = JSON.parse(card.content)
      addNode({
        ...nodeData,
        id: `${nodeData.id}-pool-${Date.now()}`,
      })
    } catch (error) {
      console.error('Failed to parse node card:', error)
    }
  }

  return (
    <div
      className="p-3 rounded-lg border border-gray-200 dark:border-gray-700 hover:border-blue-400 dark:hover:border-blue-500 cursor-pointer group relative"
      onClick={handleUseCard}
      style={{ backgroundColor: card.color }}
    >
      <div className="flex items-start justify-between">
        <div className="flex-1 min-w-0">
          <h4 className="text-sm font-medium text-gray-800 dark:text-white truncate">
            {card.name}
          </h4>
          {card.content && (
            <p className="text-xs text-gray-600 dark:text-gray-400 mt-1 line-clamp-2">
              {card.content}
            </p>
          )}
        </div>

        <button
          onClick={(e) => {
            e.stopPropagation()
            onRemove()
          }}
          className="opacity-0 group-hover:opacity-100 p-1 rounded hover:bg-red-100 dark:hover:bg-red-900/30 text-red-600 dark:text-red-400"
        >
          <Trash2 className="w-3 h-3" />
        </button>
      </div>

      {card.use_count > 0 && (
        <div className="mt-2 text-xs text-gray-500 dark:text-gray-400">
          Used {card.use_count} times
        </div>
      )}
    </div>
  )
}
